            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        xr, yr = find(x), find(y)
        if xr == yr:
            return False
        if rank[xr] < rank[yr]:
            parent[xr] = yr
        elif rank[xr] > rank[yr]:
            parent[yr] = xr
        else:
            parent[yr] = xr
            rank[xr] += 1
        return True
    mst_edges = []
    total = 0.0
    needed = len(nodes) - 1
    for mr, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, mr])
            total += mr
